func buildSetupCheckResponse(flags *rootFlags) (setupCheckResponse, error) {
	cfg, configLoadable := loadSetupConfigForCheck(flags.configPath)
	explicitConfigBaseURL, hasConfigBaseURL := loadExplicitConfigBaseURLForCheck(cfg.Path)
	baseURLSource, resolvedBaseURL := setupBaseURLState(explicitConfigBaseURL, hasConfigBaseURL)
	env := classifySetupEnvironment(resolvedBaseURL, baseURLSource)
	authConfigured, authSource := setupAuthSource(cfg)
	profileNames := listSetupProfileNames()
	sort.Strings(profileNames)

	return setupCheckResponse{
		Command:      "setup check",
		Version:      version,
		LocalPreview: true,
		Safety: map[string]bool{
			"calls_straddle_api":  false,
			"calls_docs_endpoint": false,
			"executes_mcp":        false,
			"posts_webhook":       false,
			"writes_production":   false,
		},
		Config: setupConfigStatus{
			Path:          cfg.Path,
			Exists:        fileExists(cfg.Path),
			Loadable:      configLoadable,
			BaseURL:       resolvedBaseURL,
			BaseURLSource: baseURLSource,
		},
		Environment: env,
		Auth: setupAuthStatus{
			Configured: authConfigured,
			Source:     authSource,
		},
		Profiles: setupProfileStatus{
			Count: len(profileNames),
			Names: profileNames,
		},
		MCP: buildSetupMCPStatus(),
		DocsSearch: setupLocalCommandReadiness{
			LocalCommandAvailable: true,
			Command:               "straddle-pp-cli docs search",
		},
		SandboxGuide: setupLocalCommandReadiness{
			LocalCommandAvailable: true,
			Command:               "straddle-pp-cli sandbox guide",
		},
		NextSteps: setupNextSteps(env.Classification),
	}, nil
}

func loadSetupConfigForCheck(configPath string) (*config.Config, bool) {
	path := resolveSetupConfigPath(configPath)
	if data, err := os.ReadFile(path); err != nil {
		if os.IsNotExist(err) {
			return setupFallbackConfig(path), true
		}
		return setupFallbackConfig(path), false
	} else if err := toml.Unmarshal(data, &map[string]any{}); err != nil {
		return setupFallbackConfig(path), false
	}

	cfg, err := config.Load(configPath)
	if err != nil {
		return setupFallbackConfig(path), false
	}
	return cfg, true
}

func setupFallbackConfig(path string) *config.Config {
	cfg := &config.Config{Path: path}
	if token := strings.TrimSpace(os.Getenv("STRADDLE_TOKEN")); token != "" {
		cfg.StraddleToken = token
		cfg.AuthSource = "env:STRADDLE_TOKEN"
	}
	return cfg
}

func setupAuthSource(cfg *config.Config) (bool, string) {
	if cfg == nil {
		return false, "none"
	}
	configured := cfg.AuthHeaderVal != "" || cfg.AccessToken != "" || cfg.StraddleToken != ""
	source := strings.TrimSpace(cfg.AuthSource)
	if source == "" && configured {
		source = "config"
	}
	if source == "" {
		source = "none"
	}
	return configured, source
}

func setupBaseURLState(configBaseURL string, hasConfigBaseURL bool) (string, string) {
	if envBaseURL := strings.TrimSpace(os.Getenv("STRADDLE_BASE_URL")); envBaseURL != "" {
		return "env:STRADDLE_BASE_URL", envBaseURL
	}
	if hasConfigBaseURL {
		return "config", strings.TrimSpace(configBaseURL)
	}
	return "unset", ""
}

func loadExplicitConfigBaseURLForCheck(path string) (string, bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", false
	}
	var raw map[string]any
	if err := toml.Unmarshal(data, &raw); err != nil {
		return "", false
	}
	value, ok := raw["base_url"]
	if !ok {
		return "", false
	}
	baseURL, ok := value.(string)
	if !ok {
		return "", false
	}
	return strings.TrimSpace(baseURL), true
}

func classifySetupEnvironment(baseURL, source string) setupEnvironmentStatus {
	baseURL = strings.TrimSpace(baseURL)
	classification := "unset"
	if source != "unset" && baseURL != "" {
		host := setupBaseURLHost(baseURL)
		switch {
		case host == "sandbox.straddle.com":
			classification = "sandbox"
		case host == "production.straddle.com":
			classification = "production"
		default:
			classification = "custom"
		}
	}
	return setupEnvironmentStatus{
		Classification: classification,
		Source:         source,
		BaseURL:        baseURL,
	}
}

func setupBaseURLHost(baseURL string) string {
	parsed, err := url.Parse(baseURL)
	if err != nil {
		return ""
	}
	return strings.ToLower(parsed.Hostname())
}

func setupNextSteps(classification string) []string {
	steps := []string{
		"straddle-pp-cli auth set-token --stdin",
		"straddle-pp-cli docs search \"charges\" --source commands --json",
		"straddle-pp-cli sandbox guide --json",
	}
	if classification == "sandbox" {
		steps = append(steps, "straddle-pp-cli doctor --json")
	}
	return steps
}

func listSetupProfileNames() []string {
	path, ok := setupProfileStorePath()
	if !ok || !fileExists(path) {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var s profileStore
	if err := json.Unmarshal(data, &s); err != nil {
		return nil
	}
	names := make([]string, 0, len(s.Profiles))
	for name := range s.Profiles {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func setupProfileStorePath() (string, bool) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", false
	}
	return filepath.Join(home, ".straddle-pp-cli", "profiles.json"), true
}

func resolveSetupConfigPath(configPath string) string {
	if strings.TrimSpace(configPath) != "" {
		return configPath
	}
	if path := strings.TrimSpace(os.Getenv("STRADDLE_CONFIG")); path != "" {
		return path
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "straddle-pp-cli", "config.toml")
}

func buildSetupMCPStatus() setupMCPStatus {
	siblingPath := ""
	siblingExecutable := false
	if exe, err := os.Executable(); err == nil {
		siblingPath = filepath.Join(filepath.Dir(exe), "straddle-pp-mcp")
		siblingExecutable = executableFileExists(siblingPath)
	}

	sourcePath := setupMCPSourcePath()
	sourcePresent := fileExists(sourcePath)
	return setupMCPStatus{
		Available:         siblingExecutable || sourcePresent,
		SiblingPath:       siblingPath,
		SiblingExecutable: siblingExecutable,
		SourcePath:        sourcePath,
		SourcePresent:     sourcePresent,
	}
}

func setupMCPSourcePath() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return ""
	}
	moduleRoot := filepath.Clean(filepath.Join(filepath.Dir(file), "..", ".."))
	return filepath.Join(moduleRoot, "cmd", "straddle-pp-mcp", "main.go")
}

func fileExists(path string) bool {
	if strings.TrimSpace(path) == "" {
		return false
	}
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

func executableFileExists(path string) bool {
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return false
	}
	return info.Mode()&0o111 != 0
}

func printSetupCheckHuman(cmd *cobra.Command, payload setupCheckResponse) error {
	w := cmd.OutOrStdout()
	fmt.Fprintln(w, "Setup check")
	fmt.Fprintf(w, "Command: %s %s, local preview: %v\n", "straddle-pp-cli", payload.Version, payload.LocalPreview)
	fmt.Fprintf(w, "Config: %s, loadable: %v, base_url: %s\n", payload.Config.Path, payload.Config.Loadable, displayUnset(payload.Config.BaseURL))
	fmt.Fprintf(w, "Environment: %s, source: %s\n", payload.Environment.Classification, payload.Environment.Source)
	fmt.Fprintf(w, "Auth: configured: %v, source: %s\n", payload.Auth.Configured, payload.Auth.Source)
	fmt.Fprintf(w, "Profiles: %d", payload.Profiles.Count)
	if len(payload.Profiles.Names) > 0 {
		fmt.Fprintf(w, " (%s)", strings.Join(payload.Profiles.Names, ", "))
	}
	fmt.Fprintln(w)
	fmt.Fprintf(w, "MCP companion: available: %v, source present: %v\n", payload.MCP.Available, payload.MCP.SourcePresent)
	fmt.Fprintf(w, "Docs search: local command available: %v\n", payload.DocsSearch.LocalCommandAvailable)
	fmt.Fprintf(w, "Sandbox guide: local command available: %v\n", payload.SandboxGuide.LocalCommandAvailable)
	fmt.Fprintln(w, "Next steps:")
	for _, step := range payload.NextSteps {
		fmt.Fprintf(w, "  %s\n", step)
	}
	return nil
}

func displayUnset(value string) string {
	if strings.TrimSpace(value) == "" {
		return "unset"
	}
	return value
}
